-- 代储申请表仓储费*30
UPDATE `xswc_finance_assistant`.`fa_storage_agency_apply` SET `storage_fee` = IFNULL(storage_fee, 0)*30 where id > 0;
-- 代储订单表
UPDATE `xswc_finance_assistant`.`fa_storage_order` SET `storage_fee` = IFNULL(storage_fee, 0)*30 where id > 0;
-- 代储订单发布表
UPDATE `xswc_finance_assistant`.`fa_storage_order_publish` SET `storage_fee` = IFNULL(storage_fee, 0)*30 where id > 0 ;
-- 电子仓单表
UPDATE `xswc_finance_assistant`.`fa_storage_warehouse_receipt` SET `storage_fee` = IFNULL(storage_fee, 0)*30 where id > 0;


